<?php
namespace App\Http\Controllers\Admin; use App\Domain\CaseStudies\{CaseStudyManager,CaseStudyViewData}; use App\Domain\Installation\WebsiteSettings; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\CaseStudies\SaveCaseStudyRequest; use App\Models\{CaseStudy}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Validation\Rule;
class CaseStudyController extends Controller { public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without']]);$q=CaseStudy::with(['client'])->withCount('metrics')->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only'){$q->whereNotNull('archived_at');}elseif(($f['archived']??'without')==='without'){$q->whereNull('archived_at');}return view('admin.case-studies.index',['items'=>$q->orderBy('display_order')->paginate(20)->withQueryString()]);} public function create():View{return $this->editor(new CaseStudy);} public function store(SaveCaseStudyRequest $r,CaseStudyManager $m):RedirectResponse{$x=$m->save($r->validated(),null,$r->user()->id);return redirect()->route('admin.case-studies.edit',$x);} public function edit(CaseStudy $caseStudy):View{return $this->editor($caseStudy);} public function update(SaveCaseStudyRequest $r,CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{$m->save($r->validated(),$caseStudy,$r->user()->id);return back()->with('status','Saved.');} private function editor(CaseStudy $item):View{return view('admin.case-studies.editor',['item'=>$item,'clients'=>\App\Models\Client::whereNull('archived_at')->limit(200)->get(),'testimonials'=>\App\Models\Testimonial::whereNull('archived_at')->limit(200)->get()]);} public function publish(CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{$m->publish($caseStudy);return back();} public function schedule(Request $r,CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($caseStudy,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back();} public function unpublish(CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{$m->unpublish($caseStudy);return back();} public function archive(CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{$m->archive($caseStudy);return back();} public function restore(CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{$m->restore($caseStudy);return back();} public function duplicate(Request $r,CaseStudy $caseStudy,CaseStudyManager $m):RedirectResponse{return redirect()->route('admin.case-studies.edit',$m->duplicate($caseStudy,$r->user()->id));} public function move(CaseStudy $caseStudy,string $direction,CaseStudyManager $m):RedirectResponse{$m->move($caseStudy,$direction);return back();} public function preview(Request $r,CaseStudy $caseStudy,CaseStudyViewData $d):Response{return response()->view('case-studies.show',['caseStudy'=>$d->preview($caseStudy),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} }
